@Composable
private fun VectorIcon(spec: IconSpec, modifier: Modifier, color: Color, grid: Float = 24f) {
    val path = remember(spec.data) { PathParser().parsePathString(spec.data).toPath() }
    Canvas(modifier = modifier) {
        val unit = size.minDimension / grid
        val offX = (grid - spec.vbW) / 2f
        val offY = (grid - spec.vbH) / 2f
        translate(offX * unit, offY * unit) {
            scale(unit, unit, pivot = Offset.Zero) {
                drawPath(path, color)
            }
        }
    }
}

